function validate([n, startPos, s]) {
  if (!Number.isInteger(n) || n < 1 || n > 500) return 'n is an integer from 1 to 500.';
  if (!Array.isArray(startPos) || startPos.length !== 2) return 'startPos is a pair [row, col].';
  if (startPos.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'startPos must be a cell of the grid (0 to n - 1).';
  if (typeof s !== 'string' || s.length < 1 || s.length > 500) return 's needs 1 to 500 characters.';
  if (!/^[LRUD]+$/.test(s)) return "s may contain only 'L', 'R', 'U' and 'D'.";
  return null;
}

