function executeInstructions(n, startPos, s) {
  const moves = new Map([['L', [0, -1]], ['R', [0, 1]], ['U', [-1, 0]], ['D', [1, 0]]]);
  const m = s.length;
  const answer = new Array(m).fill(0);
  for (let i = 0; i < m; i++) {
    let row = startPos[0];
    let col = startPos[1];
    let count = 0;
    for (let j = i; j < m; j++) {
      const [dRow, dCol] = moves.get(s[j]);
      row += dRow;
      col += dCol;
      if (row < 0 || row >= n || col < 0 || col >= n) {
        break;
      }
      count++;
    }
    answer[i] = count;
  }
  return answer;
}

