function executeInstructions(n, startPos, s) {
  // Record every cell the whole suffix would visit, then count the leading cells that are on the grid.
  const inside = (r, c) => r >= 0 && r < n && c >= 0 && c < n;
  const result = [];
  for (let i = 0; i < s.length; i++) {
    const path = [[startPos[0], startPos[1]]];
    for (const ch of s.slice(i)) {
      const [r, c] = path[path.length - 1];
      if (ch === 'L') path.push([r, c - 1]);
      else if (ch === 'R') path.push([r, c + 1]);
      else if (ch === 'U') path.push([r - 1, c]);
      else path.push([r + 1, c]);
    }
    let k = 0;
    while (k + 1 < path.length && inside(path[k + 1][0], path[k + 1][1])) k++;
    result.push(k);
  }
  return result;
}

