function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'LRUD';
  const n = size === 'large' ? (rand() < 0.3 ? 500 : int(1, 40)) : int(1, 4);
  const m = size === 'large' ? 500 : int(1, 9);
  const startPos = [int(0, n - 1), int(0, n - 1)];
  let s = '';
  for (let i = 0; i < m; i++) s += letters[int(0, 3)];
  return [n, startPos, s];
}
